INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (1,0,24,'Rookie','Build your foundation: play Deathmatch 20 min daily, keep sensitivity between 45-65 (no gyro), use 3-finger claw when comfortable, and focus on chest-level crosshair placement first.');
INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (2,25,44,'Casual','Consistent fighter: add gyroscope for spray control (+15 headshot % over time), pre-aim doorways and common angles, drag headshot at close range and tap at mid range.');
INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (3,45,64,'Competitive','Solid marksman: fine-tune sensitivity adjusting only ±3 points weekly, learn flick + drag combos per weapon, and record your gameplay to review deaths.');
INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (4,65,79,'Pro','Advanced shooter: use the device-specific RAM preset from Sensitivity Finder, master peek + one-tap headshot, and keep K/D training in Clash Squad ranked.');
INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (5,80,89,'Elite','Top-tier player: muscle memory is built so avoid changing sensitivity, practice quick-scoping AWM/M82B, and warm up 10 min before ranked pushes.');
INSERT OR IGNORE INTO ff_headshot_tips (id, rating_min, rating_max, tier, tip_text) VALUES (6,90,99,'Legend','Headshot machine: only tweak free-look and leave combat values alone, mentor others since consistency is your edge, and stream or post clips to analyze further.');
INSERT OR IGNORE INTO ff_news (id, title, body, category, published_at, created_at) VALUES (1,'Free Fire OB Update — New Balance Changes','The latest OB patch adjusts weapon recoil, fixes emote glitches, and introduces a new ranked season reward track. Check the official Garena patch notes for full details.','Patch Notes','2026-08-18T00:00:00Z','2026-08-18T00:00:00Z');
INSERT OR IGNORE INTO ff_news (id, title, body, category, published_at, created_at) VALUES (2,'Diamond Royale: New Bundle Alert','A limited-time bundle just landed in Diamond Royale — grab it before the rotation ends this weekend.','Events','2026-08-16T00:00:00Z','2026-08-16T00:00:00Z');
INSERT OR IGNORE INTO ff_news (id, title, body, category, published_at, created_at) VALUES (3,'Ranked Season Reset — Rank Up Tips','New season means rank reset. Push your rank early in the week when queues are faster; play CS for safe rank points.','Ranked','2026-08-14T00:00:00Z','2026-08-14T00:00:00Z');
INSERT OR IGNORE INTO ff_news (id, title, body, category, published_at, created_at) VALUES (4,'Weekly Event: Login Rewards','Log in daily this week for free gold, evolution weapon shards, and character fragments.','Events','2026-08-12T00:00:00Z','2026-08-12T00:00:00Z');
INSERT OR IGNORE INTO ff_news (id, title, body, category, published_at, created_at) VALUES (5,'RNS BIGBULL VIP Hub Milestone','VIP Hub passed a new member milestone — thank you to all lifetime VIP members for the support!','Community','2026-08-20T00:00:00Z','2026-08-20T00:00:00Z');
