INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('ffallinone','FF All-in-One Tool','["Tap the FF All-in-One card in VIP Hub","Enter your Free Fire UID on the partner site","Choose the service you want (likes, level, etc.)","Confirm and wait for processing"]','["Your UID must be correct — check it in-game","Processing can take a few minutes during peak hours","If it fails, try again after 10 minutes"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('bio','Bio Tool','["Open the Bio Tool from the main dashboard","Pick a template or write your own bio","Tap Preview to see how it looks","Tap Copy and paste it into Instagram/WhatsApp"]','["Keep your bio under 150 characters for Instagram","Gamer templates are ready to use with one tap"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('ffbind','FF UID Binding','["Open FF Bind from VIP Hub","Enter your Free Fire UID","Confirm the binding on the partner site","Wait for the success message"]','["Bind once — it stays linked to your UID","Use your in-game UID, not IGN"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('ffemote','FF Emotes','["Choose an emote from the VIP Hub list","Enter your UID when prompted","Confirm on the partner site","Emote arrives in your game vault"]','["Not all emotes are available every day — check back","Vault space is limited in-game"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('fflikes','FF Likes','["Open FF Likes from VIP Hub","Enter your UID and post link if asked","Choose like count","Confirm and wait"]','["Likes arrive gradually — normal and safe","Do not spam the request button"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('gift','FF Gift Tool','["Open the Gift tool in VIP Hub","Enter your UID","Select the gift option","Confirm on the partner page"]','["Gifts depend on partner availability","Check the tool status is Online first"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('glory','FF Glory','["Open Glory from VIP Hub","Sign in on the partner portal if asked","Follow the on-screen steps","Collect your result in-game"]','["Use the same device you play on","Keep your session active until done"]','2026-08-20T00:00:00Z');
INSERT OR IGNORE INTO vip_guide_cards (tool_id, title, steps_json, tips_json, created_at) VALUES ('reseller','Reseller Panel','["Open Reseller from VIP Hub","Log in with your reseller credentials","Place orders from the dashboard","Track status under History"]','["Balance is managed by the panel admin","Orders process in queue order"]','2026-08-20T00:00:00Z');
